def find_nodes(tree, context_id, tag):
    if not isinstance(context_id, str) or not isinstance(tag, str):
        raise ValueError('arguments must be strings')
    seen_ids = set()
    active = set()

    def validate(node):
        if not isinstance(node, dict) or set(node.keys()) != {'id', 'tag', 'children'}:
            raise ValueError('invalid node')
        if not isinstance(node['id'], str) or not isinstance(node['tag'], str) or not isinstance(node['children'], list):
            raise ValueError('invalid node')
        marker = id(node)
        if marker in active or node['id'] in seen_ids:
            raise ValueError('cycle or duplicate id')
        active.add(marker)
        seen_ids.add(node['id'])
        for child in node['children']:
            validate(child)
        active.remove(marker)

    validate(tree)
    context = None

    def locate(node):
        nonlocal context
        if node['id'] == context_id:
            context = node
        for child in node['children']:
            locate(child)

    locate(tree)
    if context is None:
        return []
    result = []

    def collect(node):
        if node['tag'] == tag:
            result.append({'id': node['id'], 'tag': node['tag']})
        for child in node['children']:
            collect(child)

    collect(context)
    return result
```

