import unittest

from solution import find_nodes


class FindNodesTests(unittest.TestCase):
    def setUp(self):
        self.tree = {
            'id': 'root',
            'tag': 'match',
            'children': [
                {
                    'id': 'a',
                    'tag': 'match',
                    'children': [
                        {'id': 'a1', 'tag': 'other', 'children': []},
                        {'id': 'a2', 'tag': 'match', 'children': []},
                    ],
                },
                {
                    'id': 'b',
                    'tag': 'other',
                    'children': [
                        {'id': 'b1', 'tag': 'match', 'children': []},
                    ],
                },
            ],
        }

    def test_descendants_only_in_preorder(self):
        result = find_nodes(self.tree, 'root', 'match')
        self.assertEqual(result, [
            {'id': 'a', 'tag': 'match'},
            {'id': 'a2', 'tag': 'match'},
            {'id': 'b1', 'tag': 'match'},
        ])
        self.assertNotIn({'id': 'root', 'tag': 'match'}, result)

    def test_context_is_excluded_but_its_descendants_are_examined(self):
        self.assertEqual(find_nodes(self.tree, 'a', 'match'), [{'id': 'a2', 'tag': 'match'}])
        self.assertEqual(find_nodes(self.tree, 'a2', 'match'), [])
        self.assertEqual(find_nodes(self.tree, 'missing', 'match'), [])

    def test_empty_strings_and_fresh_output(self):
        tree = {'id': '', 'tag': '', 'children': [{'id': 'child', 'tag': '', 'children': []}]}
        first = find_nodes(tree, '', '')
        second = find_nodes(tree, '', '')
        self.assertEqual(first, [{'id': 'child', 'tag': ''}])
        self.assertIsNot(first, second)
        self.assertIsNot(first[0], second[0])
        first[0]['id'] = 'changed'
        self.assertEqual(tree['children'][0]['id'], 'child')

    def test_invalid_arguments_and_nodes(self):
        invalid_calls = [
            lambda: find_nodes(self.tree, None, 'x'),
            lambda: find_nodes(self.tree, 'root', None),
            lambda: find_nodes([], 'x', 'y'),
            lambda: find_nodes({'id': 'x', 'tag': 'y'}, 'x', 'y'),
            lambda: find_nodes({'id': 1, 'tag': 'y', 'children': []}, 'x', 'y'),
            lambda: find_nodes({'id': 'x', 'tag': 1, 'children': []}, 'x', 'y'),
            lambda: find_nodes({'id': 'x', 'tag': 'y', 'children': ()}, 'x', 'y'),
            lambda: find_nodes({'id': 'x', 'tag': 'y', 'children': [], 'extra': 1}, 'x', 'y'),
        ]
        for call in invalid_calls:
            with self.subTest(call=call):
                with self.assertRaises(ValueError):
                    call()

    def test_duplicate_ids_and_cycles_are_rejected(self):
        duplicate = {
            'id': 'root', 'tag': 'x', 'children': [
                {'id': 'same', 'tag': 'x', 'children': []},
                {'id': 'same', 'tag': 'y', 'children': []},
            ]
        }
        cyclic = {'id': 'root', 'tag': 'x', 'children': []}
        cyclic['children'].append(cyclic)
        for tree in (duplicate, cyclic):
            with self.assertRaises(ValueError):
                find_nodes(tree, 'root', 'x')


if __name__ == '__main__':
    unittest.main()

